<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
define('MEDICINE_POLICY_LIBRARY',true);
require __DIR__.'/medicine-policy.php';

class MedicineBootstrapMemory extends MedicineV1Memory
{
    public function authorityInitialized():bool {return $this->grantRows!==[];}
}
function medicineBootstrapFixture():array {
    [$original]=medicineFixture();$inner=new MedicineV1Inner();$inner->data=$original->data;
    $repo=new MedicineBootstrapMemory($inner);$inner->governance=$repo;
    $policy=new MedicineV1Policy(['owner_bootstrap'=>['owner_user_id'=>1,'administrator_user_id'=>1,'decision_reference'=>'SYNTHETIC_OWNER_CHOICE_A','policy_version'=>'initial-owner-v1']]);
    return [$repo,...medicineGovernanceObjects($repo,$policy)];
}
function medicineBootstrapInput():array {return ['user_id'=>1,'capability'=>'administrator','scope'=>'catalog','decision_reference'=>'SYNTHETIC_OWNER_CHOICE_A','expires_at'=>null,'rationale'=>'SYNTHETIC explicit owner establishment'];}
if(defined('MEDICINE_BOOTSTRAP_LIBRARY')){return;}
medicineTest('owner designation is inert before explicit establishment',function(){[$r,$s,$a,$authority,$e,$p]=medicineBootstrapFixture();medicineCheck($p->bootstrapOwner(1)&&!$p->bootstrapOwner(2));medicineReject(fn()=>$authority->requireOperator(1,'administrator'),403);medicineReject(fn()=>$authority->requireOperator(1,'deployment'),403);medicineCheck($r->grantRows===[]);});
medicineTest('initial administrator only with immutable attributed establishment event',function(){[$r,$s,$a,$authority]=medicineBootstrapFixture();$result=$s->bootstrapAdministrator(medicineBootstrapInput());$authority->requireOperator(1,'administrator');$g=$r->grant($result['grant_id']);$event=$r->event($result['event_id']);medicineCheck($g['user_id']===1&&$g['granted_by']===1&&$g['capability']==='administrator'&&$g['scope']==='catalog');medicineCheck($event['action']==='grant'&&$event['actor_id']===1&&$event['new_state']==='active');medicineCheck(json_decode($event['snapshot_json'],true)['establishment']['mechanism']==='initial_owner_bootstrap');medicineCheck(count($r->grantRows)===1&&count($r->eventRows)===1);foreach(['deployment','registry'] as $cap){medicineReject(fn()=>$authority->requireOperator(1,$cap),403);}foreach(['contributor','reviewer'] as $cap){medicineReject(fn()=>$authority->requireGovernance(1,$cap,'composition'),403);}});
foreach([0,2,7,8] as $actor){medicineTest('forged inactive or absent bootstrap actor '.$actor,function()use($actor){[$r,$s,$a]=medicineBootstrapFixture();$a->actorId=$actor;medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),403);medicineCheck($r->grantRows===[]);});}
foreach(['user_id'=>2,'capability'=>'deployment','scope'=>'composition','decision_reference'=>'FORGED','reviewer_id'=>2,'qualification_reference'=>'FORGED','skipVerification'=>true] as $field=>$value){medicineTest('reject bootstrap field substitution '.$field,function()use($field,$value){[$r,$s]=medicineBootstrapFixture();$input=medicineBootstrapInput();$input[$field]=$value;medicineReject(fn()=>$s->bootstrapAdministrator($input),in_array($field,['user_id','decision_reference'],true)?403:422);medicineCheck($r->grantRows===[]);});}
foreach(['1 OR 1=1','1; DROP TABLE users',[],true] as $id){medicineTest('bootstrap candidate injection/type rejected '.json_encode($id),function()use($id){[$r,$s]=medicineBootstrapFixture();$input=medicineBootstrapInput();$input['user_id']=$id;medicineReject(fn()=>$s->bootstrapAdministrator($input),422);medicineCheck($r->grantRows===[]);});}
medicineTest('ordinary owner self grants remain forbidden before and after bootstrap',function(){[$r,$s]=medicineBootstrapFixture();$input=medicineBootstrapInput();unset($input['decision_reference']);medicineReject(fn()=>$s->grantAuthority($input),403);$s->bootstrapAdministrator(medicineBootstrapInput());foreach(['administrator','contributor','deployment'] as $cap){$input['capability']=$cap;medicineReject(fn()=>$s->grantAuthority($input),403);}});
medicineTest('bootstrap remains closed after initial administrator revocation',function(){[$r,$s,$a,$authority]=medicineBootstrapFixture();$g=$s->bootstrapAdministrator(medicineBootstrapInput());$s->grantAuthority(['user_id'=>2,'capability'=>'administrator','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'SYNTHETIC delegate']);$s->revokeAuthority($g['grant_id'],'SYNTHETIC owner revokes initial grant');medicineReject(fn()=>$authority->requireOperator(1,'administrator'),403);medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),409);medicineCheck(count($r->events('grant',$g['grant_id']))===2);});
medicineTest('bootstrap cannot overwrite unrelated or expired historical authority',function(){[$r,$s]=medicineBootstrapFixture();$r->insertGrant(['user_id'=>2,'capability'=>'contributor','scope'=>'composition','is_active'=>0,'granted_by'=>1,'granted_at'=>'2020-01-01 00:00:00.000001','expires_at'=>'2021-01-01 00:00:00.000001']);medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),409);});
medicineTest('bootstrap audit fault rolls back initialization',function(){[$r,$s]=medicineBootstrapFixture();$r->fault=true;medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),503);medicineCheck($r->grantRows===[]&&$r->eventRows===[]);});
medicineTest('only explicit non-expiring bootstrap and nonblank rationale permitted',function(){foreach(['2020-01-01 00:00:00.000001','bad','2030-01-01 00:00:00.000001'] as $expiry){[$r,$s]=medicineBootstrapFixture();$input=medicineBootstrapInput();$input['expires_at']=$expiry;medicineReject(fn()=>$s->bootstrapAdministrator($input),422);}[$r,$s]=medicineBootstrapFixture();$input=medicineBootstrapInput();$input['rationale']=' ';medicineReject(fn()=>$s->bootstrapAdministrator($input),422);medicineCheck($r->grantRows===[]);});
medicineTest('bootstrap owner may explicitly delegate but administrator does not confer operator/content roles',function(){[$r,$s,$a,$authority]=medicineBootstrapFixture();$s->bootstrapAdministrator(medicineBootstrapInput());$s->grantAuthority(['user_id'=>2,'capability'=>'administrator','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'SYNTHETIC delegate']);$a->actorId=2;medicineReject(fn()=>$s->grantAuthority(['user_id'=>3,'capability'=>'deployment','scope'=>'catalog','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'SYNTHETIC escalation']),403);$a->actorId=1;$g=$s->grantAuthority(['user_id'=>3,'capability'=>'contributor','scope'=>'composition','expires_at'=>'2030-01-01 00:00:00.000001','rationale'=>'SYNTHETIC author']);$authority->requireGovernance(3,'contributor','composition');$s->revokeAuthority($g['grant_id'],'SYNTHETIC revoke');medicineReject(fn()=>$authority->requireGovernance(3,'contributor','composition'),403);});
medicineTest('missing malformed configuration cannot establish authority',function(){foreach([[],['owner_user_id'=>'1','administrator_user_id'=>1],['owner_user_id'=>1,'administrator_user_id'=>1,'decision_reference'=>'','policy_version'=>'initial-owner-v1']] as $config){[$r,$s,$a,$authority,$e,$p]=medicineBootstrapFixture();$p->configuration['owner_bootstrap']=$config;medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),403);}});
medicineTest('delegated grants cannot become permanent',function(){[$r,$s]=medicineBootstrapFixture();$s->bootstrapAdministrator(medicineBootstrapInput());foreach(['administrator','contributor','deployment'] as $cap){medicineReject(fn()=>$s->grantAuthority(['user_id'=>2,'capability'=>$cap,'scope'=>$cap==='contributor'?'composition':'catalog','expires_at'=>null,'rationale'=>'SYNTHETIC nonexpiring delegate']),422);}medicineCheck(count($r->grantRows)===1);});
medicineTest('nonexpiring authority requires matching immutable event and current owner decision',function(){foreach(['missing_event','tampered_snapshot','stale_decision'] as $case){[$r,$s,$a,$authority,$e,$p]=medicineBootstrapFixture();$g=$s->bootstrapAdministrator(medicineBootstrapInput());if($case==='missing_event'){$r->eventRows=[];}elseif($case==='tampered_snapshot'){$r->eventRows[$g['event_id']]['snapshot_json']='{}';}else{$p->configuration['owner_bootstrap']['decision_reference']='CHANGED';}medicineReject(fn()=>$authority->requireOperator(1,'administrator'),403);}});
medicineTest('existing legacy owner configuration cannot introduce another initial authority root',function(){[$r,$s,$a,$authority,$e,$p]=medicineBootstrapFixture();$p->configuration['owner_user_ids']=[8];medicineReject(fn()=>$s->bootstrapAdministrator(medicineBootstrapInput()),403);medicineCheck($r->grantRows===[]);});
$failures=array_values(array_filter($medicineCases,fn($c)=>$c['status']==='FAIL'));
echo json_encode(['cases'=>count($medicineCases),'assertions'=>$medicineAssertions,'failures'=>$failures,'database_connections'=>0],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;
exit($failures?1:0);
